"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[85653],{3331:(e,r,n)=>{n.d(r,{R:()=>o,x:()=>a});var t=n(36672);const i={},s=t.createContext(i);function o(e){const r=t.useContext(s);return t.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function a(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),t.createElement(s.Provider,{value:r},e.children)}},42931:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>l,contentTitle:()=>a,default:()=>d,frontMatter:()=>o,metadata:()=>t,toc:()=>g});const t=JSON.parse('{"id":"2023/03/31","title":"2023-03-31","description":"Amerikansk lovforslag om forbud vekker bekymring for VPN-er og TikTok","source":"@site/i18n/nb/docusaurus-plugin-content-docs/current/2023/03/31.md","sourceDirName":"2023/03","slug":"/2023/03/31","permalink":"/nb/2023/03/31","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nb/docusaurus-plugin-content-docs//current/2023/03/31.md","tags":[],"version":"current","frontMatter":{"localized_date":"31. mars 2023","top_news":"Amerikansk lovforslag om forbud vekker bekymring for VPN-er og TikTok"},"sidebar":"defaultSidebar","previous":{"title":"01","permalink":"/nb/2023/04/01"},"next":{"title":"2023-03-30","permalink":"/nb/2023/03/30"}}');var i=n(23420),s=n(3331);const o={localized_date:"31. mars 2023",top_news:"Amerikansk lovforslag om forbud vekker bekymring for VPN-er og TikTok"},a="2023-03-31",l={},g=[{value:"Amerikansk lovforslag om forbud vekker bekymring for VPN-er og TikTok",id:"amerikansk-lovforslag-om-forbud-vekker-bekymring-for-vpn-er-og-tiktok",level:2},{value:"Blandet syn p\xe5 Y Combinators verdi for oppstartsbedrifter.",id:"blandet-syn-p\xe5-y-combinators-verdi-for-oppstartsbedrifter",level:2},{value:"Scratch: Popul\xe6rt visuelt programmeringsspr\xe5k for barn",id:"scratch-popul\xe6rt-visuelt-programmeringsspr\xe5k-for-barn",level:2},{value:"Utfordringer og avveininger innen LED-belysningsteknologien",id:"utfordringer-og-avveininger-innen-led-belysningsteknologien",level:2},{value:"Over halvparten av nye NPM-pakker er s\xf8ppelpost",id:"over-halvparten-av-nye-npm-pakker-er-s\xf8ppelpost",level:2},{value:"USA legger fram lovforslag med trusler mot teknologisk frihet og personvern",id:"usa-legger-fram-lovforslag-med-trusler-mot-teknologisk-frihet-og-personvern",level:2},{value:"\xc5pen kildekode 3D-gjengivelsesmotor for oppl\xe6ring og integrering",id:"\xe5pen-kildekode-3d-gjengivelsesmotor-for-oppl\xe6ring-og-integrering",level:2},{value:"Google nekter \xe5 bruke OpenAIs ChatGPT til \xe5 trene Bard.",id:"google-nekter-\xe5-bruke-openais-chatgpt-til-\xe5-trene-bard",level:2},{value:"Twitter API neglisjert, brukernes misn\xf8ye \xf8ker",id:"twitter-api-neglisjert-brukernes-misn\xf8ye-\xf8ker",level:2},{value:"Politidirekt\xf8r i San Jose siktet for narkotikasmugling.",id:"politidirekt\xf8r-i-san-jose-siktet-for-narkotikasmugling",level:2}];function k(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.header,{children:(0,i.jsx)(r.h1,{id:"2023-03-31",children:"2023-03-31"})}),"\n",(0,i.jsx)(r.h2,{id:"amerikansk-lovforslag-om-forbud-vekker-bekymring-for-vpn-er-og-tiktok",children:"Amerikansk lovforslag om forbud vekker bekymring for VPN-er og TikTok"}),"\n",(0,i.jsxs)(r.p,{children:["Et amerikansk lovforslag som st\xf8ttes av Det hvite hus og tar sikte p\xe5 \xe5 regulere internett, kan gj\xf8re VPN-er ulovlige, gi b\xf8ter p\xe5 opptil 1 million dollar og 20 \xe5rs fengsel og bli sett p\xe5 som et angrep p\xe5 borgerrettighetene. Lovforslaget har tverrpolitisk st\xf8tte, og fokuserer p\xe5 nasjonale sikkerhetshensyn knyttet til Kina og begrenser forretningsforbindelser med landet. Det er ikke sikkert at EU f\xf8lger den amerikanske trenden, ettersom landene har sin egen juridiske struktur, og TikToks forbud kan f\xf8re til harme blant unge mennesker og gjengjeldelse mot den amerikanske regjeringen. Kritikerne av forbudet hevder at det truer personvernet og ytringsfriheten.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35366955",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://www.youtube.com/watch?v=FWQGA_n5Z4M",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"blandet-syn-p\xe5-y-combinators-verdi-for-oppstartsbedrifter",children:"Blandet syn p\xe5 Y Combinators verdi for oppstartsbedrifter."}),"\n",(0,i.jsxs)(r.p,{children:["Meningene om verdien av Y Combinator (YC) for oppstartsbedrifter er blandede, avhengig av individuelle perspektiver og behov. Mens noen verdsetter YCs nettverk og mentorskap, kritiserer andre r\xe5dene og fokuset p\xe5 kortsiktige m\xe5l. YCs omd\xf8mme og merkevare kan hjelpe til med innsamling av midler, men den ubegrensede SAFE-avtalen og vektleggingen av skalering for enhver pris passer kanskje ikke alle grunnleggere. Betydningen av fellesskapsbygging og personlige forbindelser i det eksterne formatet er ogs\xe5 omdiskutert. Til syvende og sist avhenger verdien av YC av en grunnleggers evne til \xe5 utnytte ressursene for \xe5 maksimere sjansene for suksess.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35373019",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://acecreamu.substack.com/p/is-y-combinator-worth-the-money",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"scratch-popul\xe6rt-visuelt-programmeringsspr\xe5k-for-barn",children:"Scratch: Popul\xe6rt visuelt programmeringsspr\xe5k for barn"}),"\n",(0,i.jsxs)(r.p,{children:["Scratch er et popul\xe6rt visuelt programmeringsspr\xe5k rettet mot barn, som bruker fargerike blokker i stedet for tekstbasert koding for \xe5 hjelpe dem med \xe5 l\xe6re programmeringskonsepter. Programmet inkluderer grunnleggende programmeringsprinsipper som variabler, lister, if / else og l\xf8kkekontrollflytstrukturer og hendelsesbasert samtidighet. Scratch har en enkel, brukervennlig tiln\xe6rming for \xe5 oppmuntre barn til \xe5 utforske beregning p\xe5 en kreativ m\xe5te, samt et sterkt fokus p\xe5 interaksjon med jevnaldrende og deling av arbeid for \xe5 f\xe5 tilbakemelding. Scratch-fellesskapet er et av de st\xf8rste kodefellesskapene i verden, med over 103 millioner brukere og 123 millioner prosjekter delt p\xe5 plattformen. Selv om det er bekymringer knyttet til uregulerte sosiale medienettverk og barn som spiller videospill i stedet for \xe5 bruke Scratch til utdanningsform\xe5l, har verkt\xf8yet inspirert mange til \xe5 bli interessert i programmering, med prosjekter som spenner fra nybegynnerkoding til avanserte programmeringsferdigheter.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35373052",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://scratch.mit.edu/about",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"utfordringer-og-avveininger-innen-led-belysningsteknologien",children:"Utfordringer og avveininger innen LED-belysningsteknologien"}),"\n",(0,i.jsxs)(r.p,{children:["LED-p\xe6rer har utfordringer med rask svikt, d\xe5rlig fargegjengivelse og spektrale likhetsindekser, d\xe5rlig utformede str\xf8mforsyninger, overoppheting og h\xf8yere kostnader for innend\xf8rs belysning. Konstantstr\xf8mforsyning er n\xf8dvendig for LED-belysning, og armaturene m\xe5 utformes annerledes enn gl\xf8dep\xe6rer for \xe5 lede bort varmen. Det er bekymringer knyttet til p\xe5liteligheten og holdbarheten til LED-p\xe6rer, selv om det finnes alternativer av h\xf8y kvalitet til en h\xf8yere pris. Det er utfordringer med \xe5 integrere LED-p\xe6rer med dimmerbrytere og sikre kompatibilitet. Flimringen og mangelen p\xe5 livlighet i LED-belysning har f\xf8rt til utvikling av nye klassifiseringssystemer og justerbare LED-p\xe6rer. Alt i alt har LED-teknologien potensial, men krever fortsatt utvikling og innovasjon.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35371750",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://nymag.com/strategist/article/led-light-bulbs-investigation.html",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"over-halvparten-av-nye-npm-pakker-er-s\xf8ppelpost",children:"Over halvparten av nye NPM-pakker er s\xf8ppelpost"}),"\n",(0,i.jsxs)(r.p,{children:["Over halvparten av nye innsendte npm-pakker er spam, og mange inneholder lenker til ondsinnede nettsteder eller tilbyr falske freebies som Fortnite V-Bucks. \xd8kningen av s\xf8ppelpost antas \xe5 v\xe6re knyttet til oppstartskurs i koding, der studenter oppfordres til \xe5 publisere pakker selv om de ikke gj\xf8r noe. Respondentene har foresl\xe5tt l\xf8sninger som automatiserte testprosesser og en web-of-trust-modell. Problemstillingen belyser etikkens komplekse natur i programvareutviklingsbransjen og spenningen mellom ytringsfrihet og privat eiendomsrett. Sikkerhetsforskere har identifisert forekomsten av spam-pakker i hele npm-registeret og unders\xf8ker dette n\xe6rmere.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35370728",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://blog.sandworm.dev/one-in-two-new-npm-packages-is-seo-spam-right-now",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"usa-legger-fram-lovforslag-med-trusler-mot-teknologisk-frihet-og-personvern",children:"USA legger fram lovforslag med trusler mot teknologisk frihet og personvern"}),"\n",(0,i.jsxs)(r.p,{children:['Den amerikanske regjeringen har foresl\xe5tt et lovforslag som vil gi enest\xe5ende makt til \xe5 forby all utenlandsk teknologi den anser som en "trussel mot nasjonal sikkerhet", og noen hevder at det kan f\xf8re til Kina-lignende sensurmakter og v\xe6re mye bredere enn f\xf8rst antatt. Det er ogs\xe5 debatt om \xe5 forby kinesisk-eide apper p\xe5 sosiale medier, og noen hevder at det er et skr\xe5plan mot sensur av informasjon, mens andre hevder at det er n\xf8dvendig for \xe5 hindre kinesiske selskaper i \xe5 stjele amerikansk teknologi og samle inn informasjon for spionasjeform\xe5l. RESTRICT Act er et lovforslag som kan brukes til \xe5 forby TikTok og VPN-er, og kritikere hevder at det kan v\xe6re i strid med det f\xf8rste grunnlovstillegget. Republikanske senatorer har ogs\xe5 foresl\xe5tt \xe5 forby f\xf8derale ansatte \xe5 bruke apper p\xe5 sosiale medier som eies av kinesiske selskaper p\xe5 grunn av bekymring for spionasje og overv\xe5king. Noen kommentatorer antyder at lovgivningen utgj\xf8r proteksjonisme fra regjeringens side, mens andre hevder at veksten i sosiale medier skader mental helse og bidrar til manipulering av opinionen.\n',(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35369075",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://www.vice.com/en/article/4a3ddb/restrict-act-insanely-broad-ban-tiktok-vpns",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"\xe5pen-kildekode-3d-gjengivelsesmotor-for-oppl\xe6ring-og-integrering",children:"\xc5pen kildekode 3D-gjengivelsesmotor for oppl\xe6ring og integrering"}),"\n",(0,i.jsxs)(r.p,{children:["En StratusGFX 3D-gjengivelsesmotor med \xe5pen kildekode er gitt ut av en utvikler for at folk skal kunne integrere gjengivelseskoden i andre motorer eller bruke den som en pedagogisk ressurs. Funksjonene inkluderer sanntidsrefleksjoner, skygger og full st\xf8tte for PBR-skyggelegging, men den st\xf8tter forel\xf8pig bare OpenGL. Skaperen vurderer \xe5 portere renderen til Vulkan for \xe5 forbedre kompatibilitet p\xe5 tvers av plattformer. StratusGFX-motoren er designet for \xe5 maksimere realisme, men med reservekompromissfunksjoner for mindre kraftig maskinvare, og arkitekturen er tilgjengelig p\xe5 Github for Windows og Linux. Motoren er i pre-release/beta-release, og betydelige feil og ustabilitet b\xf8r forventes.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35370284",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://github.com/KTStephano/StratusGFX",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"google-nekter-\xe5-bruke-openais-chatgpt-til-\xe5-trene-bard",children:"Google nekter \xe5 bruke OpenAIs ChatGPT til \xe5 trene Bard."}),"\n",(0,i.jsxs)(r.p,{children:["Google benekter \xe5 bruke OpenAIs ChatGPT for \xe5 trene Bard, en ny spr\xe5kmodell. Det har blitt reist bekymringer om etikken ved \xe5 trene en stor spr\xe5kmodell med resultatene fra en annen kommersielt kontrollert LLM. OpenAIs tjenestevilk\xe5r forbyr oppl\xe6ring av konkurrerende modeller via ML-utgangene, men Google er ikke bundet av dette. En tidligere Google-ansatt hevdet at de brukte OpenAI-data, men Google benekter dette. AI-generert materiale er ikke opphavsrettslig beskyttet, og trening p\xe5 andre modellresultater er tillatt. Noen hevder at det kan v\xe6re moralsk forsvarlig \xe5 stjele fra ChatGPT siden det var gruppekilder, men at treningsmodeller p\xe5 andre AI-genererte data kan h\xe5ndheve d\xe5rlige data.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35370915",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://twitter.com/steventey/status/1641267979399704576",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"twitter-api-neglisjert-brukernes-misn\xf8ye-\xf8ker",children:"Twitter API neglisjert, brukernes misn\xf8ye \xf8ker"}),"\n",(0,i.jsxs)(r.p,{children:["Twitter API blir angivelig ikke vedlikeholdt, noe som f\xf8rer til ustabilitetsproblemer for brukerne. Noen brukere har rapportert at de f\xf8ler seg fremmedgjort fra tjenesten p\xe5 grunn av nedgangen i vitenskapelig artikkelinnhold og \xf8kt andel provoserende eller st\xf8tende innhold. Mange sosiale medieplattformer bruker algoritmiske feeder, men standardinnstillinger er viktige fordi de p\xe5virker brukeratferden. Twitter-brukere opplever problemer som interne serverfeil og problemer med \xe5 f\xe5 tilgang til nettstedet, noe som f\xf8rer til at noen bytter til alternative plattformer som Mastodon. Twitters nylige ustabilitetsproblemer har f\xe5tt noen brukere til \xe5 redusere bruken. Til tross for disse bekymringene mener noen at Twitters vekst under Musks ledelse tyder p\xe5 at plattformen vil fortsette \xe5 blomstre, med eller uten sine hengivne brukere. Elon Musks beslutning om \xe5 begrense tilgangen til Twitters API skaper kontroverser, og kritikere beskylder ham for med vilje \xe5 kj\xf8re Twitter i bakken. Twitters API er n\xe5 i praksis ikke vedlikeholdt, med bare \xe9n ansatt som regelmessig legger ut innlegg p\xe5 Twitter Developers-forumet og utelukkende fokuserer p\xe5 Ads API.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35370152",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://snarfed.org/the-twitter-api-is-now-effectively-unmaintained",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"politidirekt\xf8r-i-san-jose-siktet-for-narkotikasmugling",children:"Politidirekt\xf8r i San Jose siktet for narkotikasmugling."}),"\n",(0,i.jsxs)(r.p,{children:["Administrerende direkt\xf8r for San Jose Police Officers Association, Sonia Rosa Segovia, er siktet for \xe5 ha smuglet fentanyl til USA og drevet en narkotikavirksomhet delvis utenfor kontoret. Segovia skal ha brukt foreningens adresse til \xe5 sende pakker til kunder og diskutert politiets virksomhet med leverand\xf8rene sine. Minst \xe9n av kundene hennes d\xf8de av en overdose, og hun st\xe5r overfor flere narkotikarelaterte siktelser. Andre tilfeller av politifolk involvert i narkotikahandel har reist sp\xf8rsm\xe5l om politiets rolle i den ulovlige narkotikahandelen, og noen foresl\xe5r legalisering som en l\xf8sning. Samtalen om legalisering av narkotika ber\xf8rer ogs\xe5 eksterne virkninger og behovet for st\xf8ttesystemer. Joanne Southerland, administrerende direkt\xf8r i politiets fagforening i San Jose, er ogs\xe5 tiltalt for narkotikasmugling, og Joanne Segovia, en ansatt i politiets fagforening, er tiltalt for \xe5 ha importert metamfetamin til USA. Disse sakene understreker behovet for l\xf8sninger for \xe5 bekjempe narkotikasmugling og -avhengighet, blant annet kulturelle endringer og m\xe5lrettede rettsh\xe5ndhevingstiltak.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35376488",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://www.washingtonexaminer.com/news/crime/san-jose-police-union-director-smuggle-fentanyl-charge",children:"Original Post"}),"."]})]})}function d(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(k,{...e})}):k(e)}}}]);